$ErrorActionPreference = "Stop"
$Utf8Bom = New-Object System.Text.UTF8Encoding($true)

function Normalize-Lf([string]$Text) {
    if ($null -eq $Text) { return "" }
    return $Text.Replace("`r`n", "`n").Replace("`r", "`n")
}
function Read-Utf8([string]$Path) { return [IO.File]::ReadAllText($Path, [Text.Encoding]::UTF8) }
function Write-Utf8Bom([string]$Path, [string]$Text) { [IO.File]::WriteAllText($Path, (Normalize-Lf $Text), $Utf8Bom) }
function Decode-Text([string]$Value) { return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value)) }

function Replace-CSharpMethod([string]$Text, [string]$Signature, [string]$Replacement, [string]$Label) {
    $pattern = '(?ms)^(?<indent>[ \t]+)' + [regex]::Escape($Signature) + '\r?\n\k<indent>\{.*?^\k<indent>\}\r?\n'
    $regex = New-Object Text.RegularExpressions.Regex($pattern,
        ([Text.RegularExpressions.RegexOptions]::Singleline -bor [Text.RegularExpressions.RegexOptions]::Multiline))
    $matches = $regex.Matches($Text)
    if ($matches.Count -ne 1) { throw "$Label 수정 지점 수가 $($matches.Count)개입니다." }
    $match = $matches[0]
    return $Text.Substring(0,$match.Index) + (Normalize-Lf $Replacement) + "`n" + $Text.Substring($match.Index+$match.Length)
}

function Assert-Braces([string]$Path) {
    $text = Read-Utf8 $Path
    $brace = 0; $paren = 0; $bracket = 0
    $inString = $false; $inChar = $false; $lineComment = $false; $blockComment = $false; $escaped = $false
    for ($i=0; $i -lt $text.Length; $i++) {
        $c=$text[$i]; $n=if($i+1-lt$text.Length){$text[$i+1]}else{[char]0}
        if($lineComment){if($c-eq"`n"){$lineComment=$false};continue}
        if($blockComment){if($c-eq'*'-and$n-eq'/'){$blockComment=$false;$i++};continue}
        if($inString){if($escaped){$escaped=$false;continue};if($c-eq'\'){$escaped=$true;continue};if($c-eq'"'){$inString=$false};continue}
        if($inChar){if($escaped){$escaped=$false;continue};if($c-eq'\'){$escaped=$true;continue};if($c-eq"'"){$inChar=$false};continue}
        if($c-eq'/'-and$n-eq'/'){$lineComment=$true;$i++;continue}
        if($c-eq'/'-and$n-eq'*'){$blockComment=$true;$i++;continue}
        if($c-eq'"'){$inString=$true;continue}
        if($c-eq"'"){$inChar=$true;continue}
        switch($c){'{ ' {} '{'{$brace++}'}'{$brace--}'('{$paren++}')'{$paren--}'['{$bracket++}']'{$bracket--}}
        if($brace-lt0-or$paren-lt0-or$bracket-lt0){throw "괄호가 먼저 닫혔습니다: $Path"}
    }
    if($brace-ne0-or$paren-ne0-or$bracket-ne0-or$inString-or$inChar-or$blockComment){throw "괄호/문자열 균형 오류: $Path"}
}

$ProjectRoot = $env:DOBAK_V20_PROJECT_ROOT
if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { throw "DOBAK_V20_PROJECT_ROOT가 설정되지 않았습니다." }
$PayloadJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$Payload = $PayloadJson | ConvertFrom-Json

$DirectorPath = Join-Path $ProjectRoot 'Assets\Tablet\Script\ScenarioV3Director.cs'
$FlowPath = Join-Path $ProjectRoot 'Assets\Tablet\Script\GameFlowManager.cs'
$CoinPath = Join-Path $ProjectRoot 'Assets\Junsang\Scripts\Bank\CoinManager.cs'
$CasinoPath = Join-Path $ProjectRoot 'Assets\Junsang\Scripts\Casino\CasinoUIManager.cs'
$SlotPath = Join-Path $ProjectRoot 'Assets\Junsang\Scripts\SlotMachine\SlotMachineManager.cs'
$ScenarioPath = Join-Path $ProjectRoot 'Assets\Resources\ScenarioV3.csv'

$Director = Normalize-Lf (Read-Utf8 $DirectorPath)
foreach ($entry in $Payload.methods.director.PSObject.Properties) {
    $Director = Replace-CSharpMethod $Director ([string]$entry.Name) (Decode-Text ([string]$entry.Value)) "Director $($entry.Name)"
}
$Director = $Director.Replace('엄마. 교통카드 충전해야 하는데 오만 원만 보내주면 안 돼?', '엄마. 교통카드 충전해야 하는데 5만 원만 보내주면 안 돼?')
$Director = $Director.Replace('서준아. 미안한데 지금 급하게 오만 원만 빌려줄 수 있어? 다음 주에 꼭 갚을게.', '서준아. 미안한데 지금 5만 원만 빌려줄 수 있어? 다음 주에 꼭 갚을게.')
$Director = $Director.Replace('오늘은 이만 자자. 취침 앱을 열어서 하루를 마무리하자.', '오늘 일정은 모두 끝냈다. 도박 앱도 눈에 들어오고, 피곤하기도 한데.... 어떻게 할지 정해야겠다.')
$Director = $Director.Replace('종례도 끝났다. 오늘 해야 할 일을 확인하고 집에 가자.', '종례도 끝났다. 집에 가서 남은 일정을 확인하자.')
Write-Utf8Bom $DirectorPath $Director

$Flow = Normalize-Lf (Read-Utf8 $FlowPath)
if (-not $Flow.Contains('lateMapCueShownDay')) {
    $anchor = '    private void Awake()'
    $index = $Flow.IndexOf($anchor, [StringComparison]::Ordinal)
    if ($index -lt 0) { throw 'GameFlow lateMapCueShownDay 삽입 지점을 찾지 못했습니다.' }
    $Flow = $Flow.Substring(0,$index) + '    private int lateMapCueShownDay = -1; // DOBak V20 late-map cue' + "`n`n" + $Flow.Substring($index)
}
foreach ($entry in $Payload.methods.flow.PSObject.Properties) {
    $Flow = Replace-CSharpMethod $Flow ([string]$entry.Name) (Decode-Text ([string]$entry.Value)) "GameFlow $($entry.Name)"
}
if (-not $Flow.Contains('private bool TryShowLateMapCue()')) {
    $signature = '    public void TravelTo(string rawLocation)'
    $index = $Flow.IndexOf($signature, [StringComparison]::Ordinal)
    if ($index -lt 0) { throw 'TryShowLateMapCue 삽입 지점을 찾지 못했습니다.' }
    $Flow = $Flow.Substring(0,$index) + (Decode-Text '') + $Flow.Substring($index)
}
$Flow = $Flow.Replace('ShowFeedback("환전할 사이트 포인트가 없다.");','ShowFeedback("환전할 금액이 없다.");')
$Flow = $Flow.Replace('ShowFeedback($"{points:N0}P가 {won:N0}원으로 정상 환전되었다.");','ShowFeedback($"{won:N0}원이 통장으로 자동 환전됐다.");')
$Flow = $Flow.Replace('종례도 끝났다. 오늘 해야 할 일을 확인하고 집에 가자.','종례도 끝났다. 집에 가서 남은 일정을 확인하자.')
Write-Utf8Bom $FlowPath $Flow

$Coin = Normalize-Lf (Read-Utf8 $CoinPath)
$Coin = $Coin.Replace('AddRecord("사이트 포인트 충전", -amount, TransactionScope.BankToCasinoCharge);','AddRecord("도박 앱 충전", -amount, TransactionScope.BankToCasinoCharge);')
$Coin = $Coin.Replace('AddRecord("사이트 포인트 환전", won, TransactionScope.CasinoToBankCashOut);','AddRecord("도박 앱 자동 환전", won, TransactionScope.CasinoToBankCashOut);')
Write-Utf8Bom $CoinPath $Coin

$Casino = Normalize-Lf (Read-Utf8 $CasinoPath)
foreach ($entry in $Payload.methods.casino.PSObject.Properties) {
    $Casino = Replace-CSharpMethod $Casino ([string]$entry.Name) (Decode-Text ([string]$entry.Value)) "CasinoUI $($entry.Name)"
}
$Casino = $Casino.Replace('지금 시작하면 추가 포인트를 받을 수 있습니다','지금 시작하면 추가 보너스를 받을 수 있습니다')
$Casino = [regex]::Replace($Casino, 'label\.text = \$"\{won:N0\}원\\n\{CoinManager\.ConvertWonToPoints\(won\):N0\}P";', 'label.text = $"{won:N0}원";')
Write-Utf8Bom $CasinoPath $Casino

$Slot = Normalize-Lf (Read-Utf8 $SlotPath)
foreach ($entry in $Payload.methods.slot.PSObject.Properties) {
    $Slot = Replace-CSharpMethod $Slot ([string]$entry.Name) (Decode-Text ([string]$entry.Value)) "Slot $($entry.Name)"
}
$Slot = $Slot.Replace('resultText.text = "크레딧이 부족합니다";', 'resultText.text = "잔액이 부족합니다";')
Write-Utf8Bom $SlotPath $Slot

$Rows = @(Import-Csv -LiteralPath $ScenarioPath)
if ($Rows.Count -eq 0) { throw 'ScenarioV3.csv가 비어 있습니다.' }
foreach ($entry in $Payload.csv_updates.PSObject.Properties) {
    $matches = @($Rows | Where-Object { [string]$_.line_id -eq [string]$entry.Name })
    if ($matches.Count -eq 0) { continue }
    if ($matches.Count -ne 1) { throw "line_id 중복: $($entry.Name)" }
    foreach ($field in $entry.Value.PSObject.Properties) {
        if ($null -eq $matches[0].PSObject.Properties[$field.Name]) { throw "CSV 열 없음: $($field.Name)" }
        $matches[0].($field.Name) = [string]$field.Value
    }
}

$VisibleColumns = @('text','choice_a_text','choice_b_text','choice_c_text')
foreach ($row in $Rows) {
    foreach ($column in $VisibleColumns) {
        $value = [string]$row.$column
        $value = $value.Replace('5,000P','5만 원').Replace('5천P','5만 원').Replace('5천 포인트','5만 원').Replace('오천 포인트','5만 원')
        $value = $value.Replace('20,000P','20만 원').Replace('2만P','20만 원').Replace('2만 포인트','20만 원').Replace('이만 포인트','20만 원')
        $value = $value.Replace('신규 가입 포인트','가입 보너스').Replace('무료 포인트','가입 보너스').Replace('공짜 포인트','가입 보너스').Replace('추천 포인트','추천 보너스')
        $row.$column = $value
    }
}
$Lines = @($Rows | ConvertTo-Csv -NoTypeInformation)
[IO.File]::WriteAllLines($ScenarioPath, [string[]]$Lines, $Utf8Bom)

# Remove obsolete runtime fixer that conflicts with daily history reset and map behavior.
foreach ($relative in @(
    'Assets\Tablet\Script\ScenarioV3FinalRuntimeFix.cs',
    'Assets\Tablet\Script\ScenarioV3FinalRuntimeFix.cs.meta'
)) {
    $path = Join-Path $ProjectRoot $relative
    if (Test-Path $path) { Remove-Item -LiteralPath $path -Force }
}

if ($Flow -notmatch 'if \(openedApp == AppType\.Map\)[\s\S]*?TryShowLateMapCue\(\);') {
    throw '지도 앱을 열 때 지각 안내를 호출하는 연결이 적용되지 않았습니다.'
}
if ($Casino -match '사이트 포인트|보유 포인트|추가 포인트|충전 완료\s+\+\{points:N0\}P') {
    throw '도박 앱 화면에 포인트 표기가 남았습니다.'
}
if ($Slot -match '\{payout:N0\}P|\{profit:N0\}P|사이트 포인트|보유 포인트') {
    throw '슬롯 화면에 포인트 표기가 남았습니다.'
}

foreach ($path in @($DirectorPath,$FlowPath,$CoinPath,$CasinoPath,$SlotPath)) { Assert-Braces $path }

$CheckRows = @(Import-Csv -LiteralPath $ScenarioPath)
$duplicates = @($CheckRows | Group-Object line_id | Where-Object { $_.Count -gt 1 })
if ($duplicates.Count -gt 0) { throw "ScenarioV3 line_id 중복: $($duplicates[0].Name)" }
$badVisible = New-Object System.Collections.Generic.List[string]
foreach ($row in $CheckRows) {
    foreach ($column in $VisibleColumns) {
        $value = [string]$row.$column
        if ($value -match '포인트|\d[\d,]*\s*P(?:\s|$)') { $badVisible.Add("$($row.line_id)/$column: $value") }
        if ($row.scene_id -ne 'd1_minjae_invite' -and $value -match '링크') { $badVisible.Add("$($row.line_id)/$column 링크 잔존: $value") }
        if ($value -match '메모해 두자|적어 두자|기록해 두자') { $badVisible.Add("$($row.line_id)/$column 수동 메모 오해: $value") }
    }
}
if ($badVisible.Count -gt 0) { throw "표시 문구 검증 실패:`n$($badVisible -join "`n")" }

$late1=@($CheckRows|Where-Object line_id -eq 'sys_late_gamble_morning_01')[0]
$late2=@($CheckRows|Where-Object line_id -eq 'sys_late_gamble_morning_02')[0]
if ($late1.arc -ne 'main' -or $late2.arc -ne 'main') { throw '밤샘 아침 배경용 arc 수정 실패' }
if (([string](@($CheckRows|Where-Object line_id -eq 'minjae_loan_accepted_01')[0].text)) -match '이번엔|이번에는') { throw '민재 첫 차용 문장에 이번 표현이 남았습니다.' }
